# frozen_string_literal: true

require "google/protobuf"
require_relative "modeler/v1/program_pb"

# quicopt/wire — a +Model+ → the +Program+ message → protobuf bytes.
#
# The generated protobuf classes (+lib/quicopt/modeler/+, regenerated by
# +gen/gen.sh+ from the vendored +program.proto+) do the encoding; this file
# supplies the node constructors on top of them and the translation from the DSL's
# collected polynomials into the message's expression trees.
#
# The forms below are shared with the Python and Julia clients, so the same model
# written in any of the three arrives as the same message:
#
#   f = c   ⇒  f − c = 0   (Zero)
#   f ≥ l   ⇒  f − l ≥ 0   (Nonneg)
#   f ≤ u   ⇒  u − f ≥ 0   (Nonneg)
#
# A unit coefficient is dropped rather than emitted as +1 * e+, an additive zero
# constant is dropped from a sum, and a sum of one term is that term.
#
# Permutations, partitions and lookup tables count from 0 in the DSL and from 1
# on the wire, and this file is the one place that shifts between the two:
#
#   route.item_at(k)  ⇒  item_at(k + 1, route) − 1
#   teams.part_of(i)  ⇒  part_of(i + 1, teams) − 1
#   teams.size_of(b)  ⇒  size_of(b + 1, teams)      (a count: not shifted)
#   dist[i, j]        ⇒  dist[i + 1, j + 1]
#
# A read used as a table position meets both shifts, and they cancel:
# +dist[route.item_at(0), …]+ goes out as +dist[item_at(1, route), …]+.
#
# The terms that switch (+quicopt/indicators+) go out as the catalog's
# +indicator+, +step+, +min+ and +max+; a +min+ or +max+ of more than two
# arguments as nested binary ones, folded from the left.
#
# Note on byte-level comparison: protobuf omits fields that hold their default
# value (+start: 0.0+) and does not fix the order of map entries, so two encodings
# of one model can differ byte for byte while meaning exactly the same thing — the
# same position the Julia client is in. Compare decoded +Program+ values in tests,
# never hex.
module Quicopt
  # Node constructors over the generated protobuf classes, and the translation
  # from the DSL's collected polynomials into the message's expression trees.
  module Wire
    # The generated protobuf classes — +Program+, +Expression+, +Constraint+, …
    # Aliased for brevity throughout this file.
    PB = Quicopt::Modeler::V1

    class << self
      # Turn +model+ into the +Program+ message the service reads.
      #
      # @param model [Quicopt::Model]
      # @return [PB::Program]
      def program(model)
        PB::Program.new(
          params: model.tables.sort_by(&:name).map { |t| param_table(t) },
          vars: model.variables.map { |v| var_decl(v) },
          objective: expression(model.objective),
          sense: model.sense,
          constraints: model.constraints.map { |c| constraint(c) },
          structures: (model.permutations + model.partitions).sort_by(&:name).map { |p| structure_decl(p) },
          blocks: model.blocks.sort_by(&:name).map { |b| block_decl(b) }
        )
      end

      # Encode a model (or an already-built +Program+) to bytes.
      #
      # @param model [Quicopt::Model, PB::Program]
      # @return [String] binary protobuf bytes
      def encode(model)
        PB::Program.encode(model.is_a?(PB::Program) ? model : program(model))
      end

      # Parse bytes back into a +Program+ — the inverse of +encode+, and the only
      # sound way to compare two encodings.
      #
      # @param bytes [String]
      # @return [PB::Program]
      def decode(bytes)
        PB::Program.decode(bytes)
      end

      # ── node constructors ──────────────────────────────────────────────────

      # A constant expression node. The +oneof+ case is always set, so a constant
      # +0.0+ survives the round-trip rather than vanishing as a protobuf default.
      def const(value)
        PB::Expression.new(constant: number(value))
      end

      # Flatten negative zero before encoding.
      #
      # IEEE keeps +-0.0+ distinct from +0.0+ — a distinct bit pattern, and a
      # distinct protobuf value — and moving a bound across an inequality
      # (<tt>f ≤ 0</tt> ⇒ <tt>0 − f ≥ 0</tt>) produces one whenever that bound
      # is zero. The Python and Julia clients send +0.0+ there, so collapse the
      # sign here rather than sending bytes that differ from theirs by a sign
      # bit.
      def number(value)
        float = value.to_f
        float.zero? ? 0.0 : float
      end

      # A reference to a flat (unindexed) variable. The +Index+ message is sent
      # present-but-empty, which is what the service expects.
      def var(name)
        PB::Expression.new(var: PB::VarRef.new(name: name, index: PB::Index.new))
      end

      # An operator application: +op+ applied to child expressions.
      def apply(op, args)
        PB::Expression.new(apply: PB::Apply.new(op: op, args: args))
      end

      # A reference to a declared permutation, by name.
      def structure(name)
        PB::Expression.new(structure: PB::StructRef.new(name: name))
      end

      # A read of the parameter table +param+ at the given positions (counted
      # from 1, as on the wire).
      def table(param, index)
        PB::Expression.new(table: PB::TableRef.new(param: param, index: index))
      end

      # +coef · expr+, dropping a unit coefficient.
      def scaled(coef, expr)
        coef == 1.0 ? expr : apply("*", [const(coef), expr])
      end

      # Fold terms into an n-ary sum, dropping additive-zero constants. No terms
      # is the zero constant; one term is itself.
      def sum(terms)
        surviving = terms.reject { |t| t.node == :constant && t.constant.zero? }
        return const(0.0) if surviving.empty?
        return surviving.first if surviving.size == 1

        apply("+", surviving)
      end

      # ── lowering ───────────────────────────────────────────────────────────

      # A collected DSL expression → the message's expression tree: the constant
      # (when nonzero), then the linear terms, then the quadratic ones — the term
      # order the Python and Julia clients use.
      #
      # @param expr [Quicopt::Expression]
      # @return [PB::Expression]
      def expression(expr)
        terms = []
        terms << const(expr.constant) unless expr.constant.zero?
        expr.linear.each { |v, c| terms << scaled(c, factor(v)) }
        expr.quadratic.each { |(a, b), c| terms << scaled(c, apply("*", [factor(a), factor(b)])) }
        sum(terms)
      end

      # One factor of a term: a variable, a read of a permutation, partition or
      # lookup table (each standing for its value counted from 0), or a term
      # that switches.
      #
      # @param factor [Quicopt::Variable, Quicopt::Placement, Quicopt::PartRead,
      #   Quicopt::TableEntry, Quicopt::Condition, Quicopt::Extremum]
      # @return [PB::Expression]
      def factor(factor)
        case factor
        when Variable then var(factor.name)
        when Placement
          apply("-", [apply(factor.op.to_s, [const(factor.position + 1), structure(factor.permutation.name)]),
                      const(1.0)])
        when PartRead then part_read(factor)
        when TableEntry then table(factor.table.name, factor.index.map { |e| one_based(e) })
        when Condition then condition(factor)
        when Extremum
          factor.args.map { |a| expression(a) }.reduce { |acc, e| apply(factor.op.to_s, [acc, e]) }
        else raise Error, "unknown factor #{factor.inspect}"
        end
      end

      # A read of a partition: the part, shifted to count from 0; the size, a
      # count, as it is.
      #
      # @param read [Quicopt::PartRead]
      # @return [PB::Expression]
      def part_read(read)
        node = apply(read.op.to_s, [const(read.position + 1), structure(read.partition.name)])
        read.op == :part_of ? apply("-", [node, const(1.0)]) : node
      end

      # A 0/1 term: +indicator(e)+, +step(e)+, or +step(tol − abs(e))+ for a
      # comparison with a tolerance.
      #
      # @param cond [Quicopt::Condition]
      # @return [PB::Expression]
      def condition(cond)
        arg = expression(cond.argument)
        case cond.op
        when :indicator then apply("indicator", [arg])
        when :step then apply("step", [arg])
        when :near then apply("step", [apply("-", [const(cond.tol), apply("abs", [arg])])])
        else raise Error, "unknown condition #{cond.op.inspect}"
        end
      end

      # A table position, counted from 0 in the DSL, as the wire's position
      # counted from 1: a whole number moves up by one, a read of a permutation
      # loses the − 1 its own shift added, and anything else gains + 1.
      #
      # @param position [Quicopt::Expression]
      # @return [PB::Expression]
      def one_based(position)
        return const(position.constant + 1) if position.constant?

        e = expression(position)
        down = e.node == :apply && e.apply.op == "-" && e.apply.args.size == 2 &&
               e.apply.args[1].node == :constant && e.apply.args[1].constant == 1.0
        down ? e.apply.args[0] : apply("+", [e, const(1.0)])
      end

      # A lookup table → +ParamTable+: one entry per cell, keyed by its positions
      # counted from 1, in row-major order.
      #
      # @param table [Quicopt::LookupTable]
      # @return [PB::ParamTable]
      def param_table(table)
        cells = table.shape.map { |extent| (0...extent).to_a }
        keys = cells.first.product(*cells.drop(1))
        PB::ParamTable.new(name: table.name, entries: keys.map do |key|
          PB::ParamEntry.new(key: PB::Index.new(elems: key.map { |k| PB::IndexElem.new(int: k + 1) }),
                             value: number(key.reduce(table.values) { |row, k| row[k] }))
        end)
      end

      # A permutation or a partition → +StructureDecl+, its start (and a
      # permutation's precedences) counted from 1.
      #
      # @param structure [Quicopt::Permutation, Quicopt::Partition]
      # @return [PB::StructureDecl]
      def structure_decl(structure)
        start = (structure.start || []).map { |k| k + 1 }
        if structure.is_a?(Partition)
          return PB::StructureDecl.new(name: structure.name, kind: "partition", size: structure.n_items,
                                       start: start, fixed: false, parts: structure.n_parts)
        end

        PB::StructureDecl.new(
          name: structure.name, kind: "permutation", size: structure.n_items, start: start, fixed: false,
          precede: structure.precedences.map { |a, b| PB::Precedence.new(before: a + 1, after: b + 1) }
        )
      end

      # A block → +BlockDecl+: its name and its variables, in the order given.
      #
      # @param block [Quicopt::Block]
      # @return [PB::BlockDecl]
      def block_decl(block)
        PB::BlockDecl.new(name: block.name,
                          members: block.variables.map { |v| PB::VarRef.new(name: v.name, index: PB::Index.new) })
      end

      # One DSL constraint row → one constraint in the message.
      #
      # @param con [Quicopt::Constraint]
      # @return [PB::Constraint]
      def constraint(con)
        f = expression(con.body)
        c = con.bound
        case con.sense
        when :eq then PB::Constraint.new(f: minus(f, c), set: con_set(:zero))
        when :ge then PB::Constraint.new(f: minus(f, c), set: con_set(:nonneg))
        when :le then PB::Constraint.new(f: geq(c, f), set: con_set(:nonneg))
        else raise Error, "unknown constraint sense #{con.sense.inspect}"
        end
      end

      # A variable declaration → +VarDecl+. Bounds are plain numbers (the message
      # can also take a bound from a parameter table, but that needs indexed
      # variables, which this DSL does not have); ±Inf passes straight through and
      # means "unbounded in that direction". A variable that may also be 0 goes
      # out with its domain, +SEMICONTINUOUS+ or +SEMIINTEGER+.
      #
      # @param variable [Quicopt::Variable]
      # @return [PB::VarDecl]
      def var_decl(variable)
        PB::VarDecl.new(name: variable.name,
                        domain: variable.domain,
                        lower: PB::Bound.new(scalar: number(variable.lower)),
                        upper: PB::Bound.new(scalar: number(variable.upper)),
                        start: number(variable.start))
      end

      private

      # +f − c+, dropping the additive zero.
      def minus(f, c)
        c.zero? ? f : apply("-", [f, const(c)])
      end

      # +u − f+ — the body of +f ≤ u+ written as +u − f ≥ 0+.
      def geq(u, f)
        apply("-", [const(u), f])
      end

      def con_set(kind)
        case kind
        when :zero then PB::ConSet.new(zero: PB::Zero.new)
        when :nonneg then PB::ConSet.new(nonneg: PB::Nonneg.new)
        end
      end
    end
  end
end
